//! Reference replay for the vector 3D Tiles and Gaussian splat Scene modules.
//!
//! Fixtures: `tests/data/scene-vector-gaussian.json`, generated by
//! `tools/cesium/generate-scene-vector-gaussian.mjs` from pinned
//! `@cesium/engine` 23.0.0. The generator drives the real Cesium modules:
//! the canvas drawing commands of `createBillboardPointCallback`, the CPU
//! `updateCommands` split of `Vector3DTilePrimitive`, the `vctr` parser of
//! `Vector3DTileContent` with real worker calls, and the instrumented
//! half-float/degree/packing helpers of `GaussianSplat3DTileContent`.

use cesium_rs::core::{
    BoundingSphere, Cartesian3, Color, Ellipsoid, JulianDate, Matrix4, Rectangle, RuntimeError, TimeStandard,
    TypedArray,
};
use cesium_rs::renderer::{Gl, GlValue, UniformFrame};
use cesium_rs::scene::{
    create_billboard_point_callback, degree_and_coef_from_attributes, draw_billboard_point, extract_sh_degree_and_coef,
    float32_to_float16, pack_spherical_harmonics_data, Camera, CameraOptions, FrameState, GaussianSplat3DTileContent,
    GaussianSplatAttribute, GaussianSplatPrimitive, GaussianSplatPrimitiveData, GaussianSplatPrimitiveOptions,
    GaussianSplatTile, GaussianSplatTileContent, GaussianSplatTilesetState, Vector3DTileBatch,
    Vector3DTileContent, Vector3DTileContentOptions, Vector3DTileGeometry, Vector3DTilePrimitive,
    Vector3DTilePrimitiveOptions, Vector3DTilePolygons, Vector3DTilePolygonsOptions, Vector3DTilePolylines,
    Vector3DTilePolylinesOptions, Vector3DTilePoints, Vector3DTilePointsOptions, HeightReference,
};
use serde_json::Value;
use std::{rc::Rc, sync::Arc};

fn fixture() -> Value {
    serde_json::from_str(include_str!("data/scene-vector-gaussian.json")).unwrap()
}

fn f64s(value: &Value) -> Vec<f64> {
    value.as_array().unwrap().iter().map(|v| v.as_f64().unwrap()).collect()
}

fn u16s(value: &Value) -> Vec<u16> {
    value.as_array().unwrap().iter().map(|v| v.as_u64().unwrap() as u16).collect()
}

fn u32s(value: &Value) -> Vec<u32> {
    value.as_array().unwrap().iter().map(|v| v.as_u64().unwrap() as u32).collect()
}

fn css_color(value: &str) -> Color {
    Color::from_css_color_string(value).unwrap()
}

fn assert_color(actual: [u8; 4], expected: Color, alpha: f64, label: &str) {
    let expected = [
        (expected.red * 255.0).round() as u8,
        (expected.green * 255.0).round() as u8,
        (expected.blue * 255.0).round() as u8,
        (alpha * 255.0).round() as u8,
    ];
    assert_eq!(actual, expected, "{label}");
}

// =============================================================================
// createBillboardPointCallback
// =============================================================================

#[test]
fn billboard_point_callback_matches_pinned_canvas_commands() {
    for case in fixture()["createBillboardPointCallback"].as_array().unwrap() {
        let args = case["args"].as_array().unwrap();
        let center_alpha = args[0].as_f64().unwrap();
        let fill = args[1].as_str().unwrap();
        let outline = args[2].as_str().unwrap();
        let outline_width = args[3].as_f64().unwrap();
        let pixel_size = args[4].as_f64().unwrap();
        let width = case["width"].as_u64().unwrap() as u32;
        let height = case["height"].as_u64().unwrap() as u32;

        let canvas = draw_billboard_point(center_alpha, fill, outline, outline_width, pixel_size);
        assert_eq!((canvas.width, canvas.height), (width, height), "canvas size");
        assert_eq!(canvas.rgba.len(), (width * height * 4) as usize);

        // Drawing order: clear, optional outline disk, optional destination-out
        // punch, then the point disk.
        let ops: Vec<&Value> = case["ops"].as_array().unwrap().iter().collect();
        assert_eq!(ops[0]["op"], "clearRect");
        assert_eq!(ops[1]["op"], "beginPath");
        assert_eq!(ops[2]["op"], "arc");
        assert_eq!(ops[3]["op"], "closePath");
        let first_style = ops.iter().position(|op| op["op"] == "set").unwrap();
        assert_eq!(ops[first_style]["key"], "fillStyle");
        assert_eq!(
            ops[first_style]["value"].as_str().unwrap(),
            if outline_width != 0.0 { args[2].as_str().unwrap() } else { args[1].as_str().unwrap() }
        );

        if width == 0 {
            continue;
        }
        let center = [width / 2, height / 2];
        let fill_color = css_color(fill);
        let outline_color = css_color(outline);
        let inner_radius = pixel_size * 0.5;
        // The point disk covers its centre fully when the radius is at least
        // one pixel; all fixture cases satisfy this.
        if inner_radius >= 1.0 {
            let pixel = canvas.pixel(center[0], center[1]);
            let base_alpha = if outline_width != 0.0 && center_alpha < 1.0 {
                0.0
            } else if outline_width != 0.0 {
                outline_color.alpha
            } else {
                0.0
            };
            let out_alpha = fill_color.alpha + base_alpha * (1.0 - fill_color.alpha);
            if base_alpha == 0.0 {
                assert_color(pixel, fill_color, fill_color.alpha, "centre");
            } else {
                let channel = |src: f64, dst: f64| {
                    (src * fill_color.alpha + dst * base_alpha * (1.0 - fill_color.alpha)) / out_alpha
                };
                assert_color(
                    pixel,
                    Color::new(
                        channel(fill_color.red, outline_color.red),
                        channel(fill_color.green, outline_color.green),
                        channel(fill_color.blue, outline_color.blue),
                        1.0,
                    ),
                    out_alpha,
                    "centre over outline",
                );
            }
        }

        // A corner is outside both disks when it is at least one pixel beyond
        // the outline radius.
        let center_coordinate = (width as f64) * 0.5 - 0.5;
        let corner_distance = (2.0_f64).sqrt() * center_coordinate.min(center_coordinate);
        if corner_distance > (pixel_size + 2.0 * outline_width) * 0.5 + 1.0 {
            assert_eq!(canvas.pixel(0, 0), [0, 0, 0, 0], "corner");
        }
    }
}

#[test]
fn billboard_point_callback_builds_a_pixel_billboard_image() {
    let callback = create_billboard_point_callback::<GlStub>(1.0, "#ff0000", "#0000ff", 1.0, 4.0);
    match callback() {
        cesium_rs::scene::BillboardImage::Source(cesium_rs::renderer::TextureSource::Pixels { width, height, bytes }) => {
            assert_eq!((width, height), (6, 6));
            assert_eq!(bytes.len(), 6 * 6 * 4);
        }
        _ => panic!("expected immediate pixels"),
    }
}

#[derive(Clone)]
struct GlStub;
impl Gl for GlStub {
    type Object = u32;
    fn drawing_buffer_size(&self) -> Result<[u32; 2], RuntimeError> {
        Ok([8, 8])
    }
    fn invoke(&self, _: &str, _: &[GlValue<u32>]) -> Result<GlValue<u32>, RuntimeError> {
        Ok(GlValue::Null)
    }
}

